begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email) values('92000000-0000-4000-8000-000000000001','map-value@example.test');
update public.profiles set role='DISPATCHER',active=true where id='92000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','92000000-0000-4000-8000-000000000001',true);
select set_config('test.map_id',(public.create_request(gen_random_uuid(),'{"full_name":"Map fixture","phone":"+13055550191","email":null,"origin":"5011 Broadway","destination":"5001 NW 36th St","origin_location":{"label":"5011 Broadway","street":"5011 Broadway","city":"West Palm Beach","postal_code":"33407","place_id":"fixture-origin","precision":"ADDRESS"},"destination_location":{"label":"5001 NW 36th St","street":"5001 NW 36th St","city":"Miami Springs","postal_code":"33166","place_id":"fixture-destination","precision":"ADDRESS"},"move_size":"STUDIO","moving_date":null,"comments":""}')->>'id'),true);
select is((select place_id from public.addresses a join public.moving_requests r on r.origin_id=a.id where r.id=current_setting('test.map_id')::uuid),'fixture-origin','Creation preserves Google identity');
select ok((select not territorial_reviewed and suggested_mode is null from public.moving_requests where id=current_setting('test.map_id')::uuid),'Identity does not approve territory');
select set_config('test.map_payload','{"full_name":"Map fixture","phone":"+13055550191","email":null,"origin":{"street":"5011 Broadway","unit":"","city":"West Palm Beach","postal_code":"33407","state":"FL","country":"US","place_id":"fixture-origin","precision":"ADDRESS"},"destination":{"street":"5001 NW 36th St","unit":"","city":"Miami Springs","postal_code":"33166","state":"FL","country":"US","place_id":"fixture-destination","precision":"ADDRESS"},"origin_county":"OTHER_FL","destination_county":"MIAMI_DADE","territorial_reviewed":true,"comments":""}',true);
select lives_ok($$select public.edit_request(current_setting('test.map_id')::uuid,1,current_setting('test.map_payload')::jsonb)$$,'Edit supports identities');
select is((select place_id from public.addresses a join public.moving_requests r on r.origin_id=a.id where r.id=current_setting('test.map_id')::uuid),'fixture-origin','Edit retains ID');
select lives_ok($$select public.edit_request(current_setting('test.map_id')::uuid,2,(current_setting('test.map_payload')::jsonb #- '{origin,place_id}' #- '{destination,place_id}')||'{"full_name":"Changed contact"}')$$,'Older clients can edit contact');
select is((select place_id from public.addresses a join public.moving_requests r on r.origin_id=a.id where r.id=current_setting('test.map_id')::uuid),'fixture-origin','Older payload retains unchanged identity');
select lives_ok($$select public.edit_request(current_setting('test.map_id')::uuid,3,jsonb_set(current_setting('test.map_payload')::jsonb #- '{origin,place_id}', '{origin,street}','"5012 Broadway"'))$$,'Street change accepted');
select is((select place_id from public.addresses a join public.moving_requests r on r.origin_id=a.id where r.id=current_setting('test.map_id')::uuid),null::text,'Changed street clears identity');
select is((select place_id from public.addresses a join public.moving_requests r on r.destination_id=a.id where r.id=current_setting('test.map_id')::uuid),'fixture-destination','Other endpoint preserved');
select * from finish();
rollback;
